describe("doctests of sympy.integrals", () => {
  it("integrate(1/x,x)", () => {
    const x = new Sym('x');
    expect(sympyStr(integrate(pow(x, Rational.of(-1n, 1n, { gcd: 1n })), x, undefined, { conds: 'piecewise' }))).toBe('log(x)');
  });
  it("integrate(sin(x),x)", () => {
    const x = new Sym('x');
    expect(sympyStr(integrate(fn('sin', [x], { evaluate: false }), x, undefined, { conds: 'piecewise' }))).toBe('-cos(x)');
  });
});

